                    <motion.button onClick={() => { push(text); setText(""); }} whileTap={{ scale: 0.9 }} className="rounded-full flex items-center justify-center shrink-0" style={{ width: 46, height: 46, background: tokens.primaryText }}>
                      <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="#fff" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><path d="M12 19V5M5 12l7-7 7 7" /></svg>
                    </motion.button>
