const EASE = [0.6, 0, 0.4, 1];
const GENTLE = { duration: 0.55, ease: [0.4, 0, 0.2, 1] };
const STAGGER = { hidden: {}, show: { transition: { staggerChildren: 0.06, delayChildren: 0.02 } } };
const RISE = { hidden: { opacity: 0, y: 14 }, show: { opacity: 1, y: 0, transition: { type: "spring", stiffness: 380, damping: 30 } } };
const HERO = 360;
