function TimeRuler({ onChange, tone = "dark" }) {
  const [minutes, setMinutes] = useState(0);
  const drag = useRef({ down: false, startX: 0, startMinutes: 0 });
  const baseTime = useRef(new Date());
  const light = tone === "light";
  const textColor = light ? "#fff" : "#111";
  const tickColor = light ? "rgba(255,255,255,0.42)" : "rgb(17 17 17 / 15%)";
  const activeTickColor = light ? "#fff" : "#111";
  const activeHalo = light ? "0 0 0 6px rgba(255,255,255,0.16)" : "0 0 0 6px rgba(255,255,255,0.72)";
  const clamp = (value, min, max) => Math.max(min, Math.min(max, value));
  const snap = (value) => Math.round(value / 10) * 10;
  const dateFor = (value) => new Date(baseTime.current.getTime() + value * 60000);
  const format = (value) => {
    if (value === 0) return "Сейчас";
    const d = dateFor(value);
    return d.toLocaleTimeString("ru-RU", { hour: "2-digit", minute: "2-digit" });
  };
  useEffect(() => { onChange?.(dateFor(minutes), minutes); }, [minutes]);
  const shift = -minutes / 10 * 18;
  const onPointerDown = (e) => {
    drag.current = { down: true, startX: e.clientX, startMinutes: minutes };
    e.currentTarget.setPointerCapture?.(e.pointerId);
  };
  const onPointerMove = (e) => {
    if (!drag.current.down) return;
    const next = clamp(snap(drag.current.startMinutes - (e.clientX - drag.current.startX) / 1.25), -180, 360);
    setMinutes(next);
  };
  const onPointerUp = (e) => {
    drag.current.down = false;
    e.currentTarget.releasePointerCapture?.(e.pointerId);
  };
  const ticks = Array.from({ length: 73 }, (_, i) => i - 36);

  return (
    <motion.div
      onPointerDown={onPointerDown}
      onPointerMove={onPointerMove}
      onPointerUp={onPointerUp}
      onPointerCancel={onPointerUp}
      style={{ height: 92, background: "transparent", color: textColor, cursor: "grab", touchAction: "none", overflow: "hidden", position: "relative", marginBottom: 10, userSelect: "none" }}
      whileTap={{ scale: 0.992 }}
      transition={SPRING}
    >
      <motion.div
        key={minutes}
        initial={{ opacity: 0.35, y: 5 }}
        animate={{ opacity: 1, y: 0 }}
        transition={{ duration: 0.22, ease: [0.4, 0, 0.2, 1] }}
        style={{ ...T.section, fontSize: 28, fontWeight: 400, color: textColor, textAlign: "center", paddingTop: 15 }}
      >
        {format(minutes)}
      </motion.div>
      <div style={{ position: "absolute", left: 0, right: 0, bottom: 2, height: 38, overflow: "hidden" }}>
        <div
          style={{ position: "absolute", left: "50%", top: 0, display: "flex", alignItems: "flex-end", gap: 16, padding: "0 80px", transform: `translateX(calc(-50% + ${shift}px))`, transition: drag.current.down ? "none" : "transform 220ms cubic-bezier(0.4, 0, 0.2, 1)" }}
        >
          {ticks.map((tick) => (
            <span key={tick} style={{ display: "block", width: 2, height: tick === 0 ? 28 : tick % 4 === 0 ? 24 : tick % 2 === 0 ? 19 : 14, background: tick === 0 ? activeTickColor : tickColor }} />
          ))}
        </div>
        <div style={{ position: "absolute", left: "50%", top: 2, width: 2, height: 28, background: activeTickColor, transform: "translateX(-50%)", boxShadow: activeHalo }} />
      </div>
    </motion.div>
  );
}

function TerritoryMap({ onOpenChat }) {
  const [pos, setPos] = useState({ x: -260, y: -48 });
  const [activePin, setActivePin] = useState(null);
  const [tipH, setTipH] = useState(120);
  const tipRef = useRef(null);
  const [mapDate, setMapDate] = useState(new Date());
  const [mapOffsetMinutes, setMapOffsetMinutes] = useState(0);
  const mapSize = { width: 940, height: 960 };
  const drag = useRef({ down: false, x: 0, y: 0, startX: 0, startY: 0 });
  const moved = useRef(false);
  const clamp = (value, min, max) => Math.max(min, Math.min(max, value));
  const bounds = () => {
    const box = boxRef.current;
    const W = box ? box.clientWidth : 393;
    const H = box ? box.clientHeight : 872;
    return {
      minX: Math.min(0, W - mapSize.width),
      minY: Math.min(0, H - mapSize.height),
    };
  };
  const onDown = (e) => {
    e.currentTarget.setPointerCapture?.(e.pointerId);
    drag.current = { down: true, x: e.clientX, y: e.clientY, startX: pos.x, startY: pos.y };
    moved.current = false;
  };
  const onMove = (e) => {
    if (!drag.current.down) return;
    if (Math.abs(e.clientX - drag.current.x) > 4 || Math.abs(e.clientY - drag.current.y) > 4) moved.current = true;
    const b = bounds();
    setPos({
      x: clamp(drag.current.startX + e.clientX - drag.current.x, b.minX, 0),
      y: clamp(drag.current.startY + e.clientY - drag.current.y, b.minY, 0),
    });
  };
  const onUp = () => { drag.current.down = false; };
  const boxRef = useRef(null);
  const focusPin = (pin) => {
    const box = boxRef.current;
    const W = box ? box.clientWidth : 365;
    const H = box ? box.clientHeight : 680;
    const px = pin.x / 100 * mapSize.width;
    const py = pin.y / 100 * mapSize.height;
    const b = bounds();
    setPos({ x: clamp(W * 0.5 - px, b.minX, 0), y: clamp(H * 0.62 - py, b.minY, 0) });
  };
  const onMapClick = () => {
    if (!moved.current) setActivePin(null);
  };
  const hour = mapDate.getHours();
  const pinSet = hour % 4;
  const pinSets = [
    [
      { label: "Кино", x: 39, y: 31, scale: 1, text: "Через 5 минут начнется кинопоказ «Мой сосед Тоторо»" },
      { label: "Чай", x: 58, y: 55, scale: 1.18, photo: CAMPFIRE_IMAGE, text: "Через 25 минут у костра будет травяной чай и пледы" },
    ],
    [
      { label: "Закат", x: 51, y: 76, scale: 1.3, photo: VIEWPOINT_IMAGE, text: "Через 20 минут начнется закат — отсюда лучший вид" },
      { label: "Йога", x: 45, y: 45, scale: 1.1, text: "Через 40 минут начнется мягкая йога на поляне" },
      { label: "Ресторан", x: 34, y: 63, scale: 1.2, photo: RESTAURANT_IMAGE, text: "Через 15 минут откроется вечернее меню в ресторане" },
    ],
    [
      { label: "Баня", x: 61, y: 56, scale: 1.22, photo: BANYA_VIDEO, text: "Через 30 минут начнется коллективное парение. Приходите погреться!" },
      { label: "Маршрут", x: 47, y: 70, scale: 1.05, photo: TRAIL_IMAGE, text: "Через 10 минут стартует короткая прогулка к роднику" },
    ],
    [
      { label: "Костер", x: 54, y: 42, scale: 1.3, photo: CAMPFIRE_IMAGE, text: "Через 15 минут начнется вечер у костра с гитарой" },
      { label: "Смотровая", x: 66, y: 69, scale: 1.16, photo: VIEWPOINT_IMAGE, text: "Через 35 минут гид поведет на смотровую над Катунью" },
      { label: "СПА", x: 36, y: 50, scale: 1.08, photo: SPA_IMAGE, text: "Свободное окно на массаж" },
    ],
  ];
  const pins = pinSets[pinSet];
  const tooltipPin = activePin ? pins.find((pin) => pin.label === activePin) : null;
  const tooltipLeft = tooltipPin ? `clamp(12px, ${pos.x + tooltipPin.x / 100 * mapSize.width - 107}px, calc(100% - 226px))` : "12px";
  const tooltipTop = tooltipPin ? `clamp(12px, ${pos.y + tooltipPin.y / 100 * mapSize.height - 32 - tipH}px, calc(100% - 150px))` : "12px";
  const selectedMapTime = mapDate.toLocaleTimeString("ru-RU", { hour: "2-digit", minute: "2-digit" });
  const mapPopupText = (pin) => {
    if (!pin) return "";
    if (mapOffsetMinutes === 0) return pin.text;
    return pin.text.replace(/^Через \d+ минут /, `В ${selectedMapTime} `);
  };
  useEffect(() => { setActivePin(null); }, [pinSet]);
  React.useLayoutEffect(() => { if (tipRef.current) setTipH(tipRef.current.offsetHeight); }, [activePin]);
  return (
    <motion.div variants={RISE} style={{ position: "relative", width: "100%", height: "100%" }}>
      <div
        onPointerDown={onDown}
        onPointerMove={onMove}
        onPointerUp={onUp}
        onPointerCancel={onUp}
        onPointerLeave={onUp}
        ref={boxRef}
        onClick={onMapClick}
        style={{ position: "absolute", top: 0, left: 0, right: 0, bottom: 0, borderRadius: 0, overflow: "hidden", cursor: "grab", touchAction: "none", background: tokens.elevatedSurface, zIndex: 0 }}
      >
        <div style={{ position: "absolute", width: mapSize.width, height: mapSize.height, transform: `translate3d(${pos.x}px, ${pos.y}px, 0)`, transition: drag.current.down ? "none" : "transform 320ms cubic-bezier(0.60, 0.00, 0.40, 1.00)" }}>
          <img src={TERRITORY_MAP} alt="" draggable={false} style={{ position: "absolute", inset: 0, width: "100%", height: "100%", objectFit: "cover", userSelect: "none", pointerEvents: "none" }} />
          {pins.map((pin) => {
            const pinSize = 48 * (pin.scale || 1);
            return (
            <React.Fragment key={pin.label}>
              <button
                aria-label={pin.label}
                onPointerDown={(e) => e.stopPropagation()}
                onClick={(e) => {
                  e.stopPropagation();
                  const next = activePin === pin.label ? null : pin.label;
                  setActivePin(next);
                  if (next) focusPin(pin);
                }}
                style={{ position: "absolute", left: pin.x + "%", top: pin.y + "%", transform: "translate(-50%, -50%)", border: "none", background: "transparent", padding: 0, borderRadius: 999 }}
              >
                <span style={{ display: "block", width: pinSize, height: pinSize, borderRadius: 999, overflow: "hidden", boxShadow: "0 0 0 2.5px #fff, 0 3px 10px rgba(0,0,0,0.22)" }}>
                  <MediaElement src={mediaSrc(pin.photo || pin.label)} alt="" draggable={false} style={{ width: "100%", height: "100%", objectFit: "cover", display: "block", pointerEvents: "none" }} />
                </span>
              </button>
            </React.Fragment>
          );})}
        </div>
        <AnimatePresence>
          {tooltipPin && (
            <motion.div
              key={tooltipPin.label}
              ref={tipRef}
              initial={{ opacity: 0, y: 8, scale: 0.96 }}
              animate={{ opacity: 1, y: 0, scale: 1 }}
              exit={{ opacity: 0, y: 6, scale: 0.96 }}
              transition={SPRING}
              onPointerDown={(e) => e.stopPropagation()}
              onClick={(e) => e.stopPropagation()}
              style={{ position: "absolute", left: tooltipLeft, top: tooltipTop, width: 214, padding: "14px 16px", borderRadius: 16, background: tokens.surface, color: tokens.primaryText, fontSize: 16, lineHeight: 1.35, boxShadow: "0 12px 34px rgba(20,32,42,0.18)", zIndex: 4, pointerEvents: "auto" }}
            >
              <div style={{ marginBottom: 10 }}>{mapPopupText(tooltipPin)}</div>
              <button onPointerDown={(e) => e.stopPropagation()} onClick={() => { if (onOpenChat) onOpenChat(tooltipPin); setActivePin(null); }} className="rounded-full flex items-center justify-center" style={{ width: "100%", height: 40, background: tokens.primaryText }}>
                <span style={{ color: "#fff", fontSize: 16, fontWeight: 600 }}>Подробнее</span>
              </button>
            </motion.div>
          )}
        </AnimatePresence>
      </div>
      <div aria-hidden="true" style={{ position: "absolute", left: 0, right: 0, top: 0, height: 280, zIndex: 3, pointerEvents: "none", background: "linear-gradient(rgb(0 0 0 / 80%) 0%, rgb(0 0 0 / 71%) 42%, rgba(0, 0, 0, 0) 100%)" }} />
      <div onPointerDown={(e) => e.stopPropagation()} onClick={(e) => e.stopPropagation()} style={{ position: "absolute", left: 26, right: 26, top: 56, zIndex: 6, padding: 0 }}>
        <TimeRuler onChange={(date, offset) => { setMapDate(date); setMapOffsetMinutes(offset); }} tone="light" />
      </div>
    </motion.div>
  );
}

