function cover(seed) { return PHOTOS[hashStr(seed) % PHOTOS.length]; }

// проактивная карточка агента (говорит первым)
function Nudge({ text, actions = [], onAct }) {
  const [gone, setGone] = useState(false);
  return (
    <AnimatePresence>
      {!gone && (
        <motion.div layout initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} exit={{ opacity: 0, scale: 0.96 }} transition={SPRING}
          style={{ background: tokens.surface, borderRadius: 20, padding: 16, boxShadow: "0 10px 30px rgba(20,32,42,0.06)" }}>
          <div className="flex items-start gap-2.5">
            <LottieStar size={22} />
            <div style={{ ...T.body, color: tokens.primaryText, fontSize: 15 }}>{text}</div>
          </div>
          {actions.length > 0 && (
            <div className="flex gap-2 mt-3">
              {actions.map((a, i) => (
                <motion.button key={a} whileTap={{ scale: 0.96 }} onClick={() => { setGone(true); onAct && onAct(a); }}
                  className="rounded-full" style={{ padding: "10px 16px", fontSize: 14, fontWeight: 600, background: i === 0 ? tokens.primaryText : tokens.elevatedSurface, color: i === 0 ? "#fff" : tokens.secondaryText }}>{a}</motion.button>
              ))}
            </div>
          )}
        </motion.div>
      )}
    </AnimatePresence>
  );
}

// свайп-колода развлечений
function SwipeCard({ item, isTop, depth, onDecide }) {
  const x = useMotionValue(0);
  const rot = useTransform(x, [-160, 160], [-11, 11]);
  const likeOp = useTransform(x, [30, 120], [0, 1]);
  const skipOp = useTransform(x, [-120, -30], [1, 0]);
  return (
    <motion.div style={{ position: "absolute", inset: 0, x: isTop ? x : 0, rotate: isTop ? rot : 0, zIndex: 10 - depth }}
      drag={isTop ? "x" : false} dragConstraints={{ left: 0, right: 0 }} dragElastic={0.7}
      onDragEnd={(e, info) => { if (info.offset.x > 110) onDecide(true); else if (info.offset.x < -110) onDecide(false); }}
      animate={{ scale: 1 - depth * 0.04, y: depth * 12 }} transition={SPRING}>
      <div style={{ position: "absolute", inset: 0, borderRadius: 22, overflow: "hidden", background: tokens.surface, boxShadow: "0 16px 40px rgba(20,32,42,0.12)" }}>
        <MediaElement src={mediaSrc(item.photo)} alt="" style={{ position: "absolute", inset: 0, width: "100%", height: "100%", objectFit: "cover" }} />
        <div style={{ position: "absolute", inset: 0, background: "linear-gradient(to top, rgba(20,32,42,0.82) 0%, rgba(20,32,42,0.1) 52%, rgba(20,32,42,0) 100%)" }} />
        <div style={{ position: "absolute", left: 0, right: 0, bottom: 0, padding: 18 }}>
          <div className="flex gap-1.5 mb-2">
            <span className="inline-flex rounded-full" style={{ ...T.meta, padding: "5px 12px", color: "#fff", background: "rgba(255,255,255,0.22)", textTransform: "capitalize" }}>{item.when}</span>
          </div>
          <div style={{ ...T.display, color: "#fff", fontSize: 22 }}>{item.title}</div>
          <div style={{ ...T.body, color: "rgba(255,255,255,0.82)", marginTop: 4 }}>{item.desc}</div>
        </div>
        {isTop && <motion.div style={{ opacity: likeOp, position: "absolute", top: 18, left: 18, border: "3px solid #34D399", color: "#34D399", borderRadius: 10, padding: "3px 10px", fontWeight: 700, transform: "rotate(-12deg)" }}>ХОЧУ</motion.div>}
        {isTop && <motion.div style={{ opacity: skipOp, position: "absolute", top: 18, right: 18, border: "3px solid #F87171", color: "#F87171", borderRadius: 10, padding: "3px 10px", fontWeight: 700, transform: "rotate(12deg)" }}>ПОЗЖЕ</motion.div>}
      </div>
    </motion.div>
  );
}
function SwipeDeck({ items, onLike }) {
  const [idx, setIdx] = useState(0);
  const rest = items.slice(idx);
  const decide = (like) => { if (like) onLike(items[idx]); setIdx((v) => v + 1); };
  if (rest.length === 0) return (
    <div className="flex flex-col items-center justify-center text-center" style={{ height: 300, background: tokens.surface, borderRadius: 22, padding: 24 }}>
      <LottieStar size={30} />
      <div style={{ ...T.heading, marginTop: 10 }}>Готово</div>
      <div style={{ ...T.body, marginTop: 4 }}>Разложил всё, что понравилось, по дням заезда — загляните во вкладки дней.</div>
    </div>
  );
  return (
    <div>
      <div className="relative" style={{ height: 300 }}>
        <AnimatePresence>{rest.slice(0, 3).map((it, i) => <SwipeCard key={it.id} item={it} isTop={i === 0} depth={i} onDecide={decide} />)}</AnimatePresence>
      </div>
      <div className="flex items-center justify-center gap-2 mt-3" style={{ ...T.meta }}>
        <span>← позже</span><span style={{ opacity: 0.4 }}>·</span><span>хочу →</span>
      </div>
    </div>
  );
}

